def _bottles(count):
    if count == 0:
        return "no more bottles"
    if count == 1:
        return "1 bottle"
    return f"{count} bottles"


def _verse(n):
    line1 = f"{_bottles(n).capitalize()} of beer on the wall, {_bottles(n)} of beer."
    if n == 0:
        line2 = "Go to the store and buy some more, 99 bottles of beer on the wall."
    elif n == 1:
        line2 = "Take it down and pass it around, no more bottles of beer on the wall."
    else:
        line2 = f"Take one down and pass it around, {_bottles(n - 1)} of beer on the wall."
    return [line1, line2]


def recite(start, take=1):
    lines = []
    for i in range(take):
        if i > 0:
            lines.append("")
        lines.extend(_verse(start - i))
    return lines

